{
  "findings": [
    {
      "check_id": "CKV2_AWS_61",
      "title": "S3 bucket lacks a lifecycle configuration",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The bucket has no lifecycle configuration, so incomplete multipart uploads can remain indefinitely and consume storage."
    },
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "Although the current ACL is private, no account-independent bucket-level controls prevent future public ACLs or public bucket policies."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 bucket access logging is disabled",
      "resource": "aws_s3_bucket.b",
      "severity": "HIGH",
      "explanation": "The bucket does not deliver server access logs, reducing visibility into object access and unauthorized requests."
    },
    {
      "check_id": "CKV_AWS_144",
      "title": "S3 bucket lacks cross-region replication",
      "resource": "aws_s3_bucket.b",
      "severity": "MEDIUM",
      "explanation": "The bucket has no cross-region replication configuration, leaving its contents without regional disaster-recovery protection."
    }
  ],
  "patched_code": "variable "s3_logging_target_bucket_name" {
  description = "Name of an existing same-region S3 bucket configured to receive server access logs."
  type        = string
}

variable "s3_replication_destination_bucket_name" {
  description = "Name of an existing versioned S3 bucket in a different AWS region used as the replication destination."
  type        = string
}

variable "s3_replication_role_arn" {
  description = "ARN of an existing IAM role that permits S3 replication to the destination bucket."
  type        = string
}

data "aws_region" "current" {}

data "aws_s3_bucket" "replication_destination" {
  bucket = var.s3_replication_destination_bucket_name
}

resource "aws_s3_bucket" "b" {
  bucket = "my-tf-test-bucket-ggff"
  acl    = "private"
}

resource "aws_s3_bucket_public_access_block" "b" {
  bucket = aws_s3_bucket.b.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_logging" "b" {
  bucket        = aws_s3_bucket.b.id
  target_bucket = var.s3_logging_target_bucket_name
  target_prefix = "${aws_s3_bucket.b.id}/"
}

resource "aws_s3_bucket_lifecycle_configuration" "b" {
  bucket = aws_s3_bucket.b.id

  rule {
    id     = "abort-incomplete-multipart-uploads"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 7
    }
  }
}

resource "aws_s3_bucket_versioning" "b" {
  bucket = aws_s3_bucket.b.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_replication_configuration" "b" {
  depends_on = [aws_s3_bucket_versioning.b]

  bucket = aws_s3_bucket.b.id
  role   = var.s3_replication_role_arn

  rule {
    id     = "cross-region-replication"
    status = "Enabled"

    destination {
      bucket = data.aws_s3_bucket.replication_destination.arn
    }
  }

  lifecycle {
    precondition {
      condition     = data.aws_s3_bucket.replication_destination.region != data.aws_region.current.name
      error_message = "The replication destination bucket must be in a different AWS region."
    }
  }
}
",
  "fix_summary": "Added a full S3 Public Access Block, server access logging, a non-destructive lifecycle rule, versioning, and cross-region replication. Existing logging and replication infrastructure is supplied through variables rather than embedding credentials or creating unspecified destination buckets."
}
